import subprocess, os, tempfile, pathlib
EXE="/workspace/executable"
def run(args,cwd,files=None,dirs=None):
    if dirs:
        for d in dirs: os.makedirs(os.path.join(cwd,d),exist_ok=True)
    if files:
        for n,c in files.items():
            p=os.path.join(cwd,n); os.makedirs(os.path.dirname(p),exist_ok=True); open(p,"w").write(c)
    p=subprocess.run([EXE]+args,capture_output=True,text=True,cwd=cwd)
    return p.returncode,p.stdout,p.stderr

def t(desc,args,files=None,dirs=None, subcwd=None):
    with tempfile.TemporaryDirectory() as td:
        # create structure in td, then run in td/subcwd if given
        if dirs:
            for d in dirs: os.makedirs(os.path.join(td,d),exist_ok=True)
        if files:
            for n,c in files.items():
                p=os.path.join(td,n); os.makedirs(os.path.dirname(p),exist_ok=True); open(p,"w").write(c)
        cwd=os.path.join(td,subcwd) if subcwd else td
        p=subprocess.run([EXE]+args,capture_output=True,text=True,cwd=cwd)
        print(f"=== {desc} args={args} cwd_sub={subcwd} rc={p.returncode}")
        print("out:",repr(p.stdout)); print("err:",repr(p.stderr))
        for root,ds,fs in os.walk(td):
            for f in fs:
                fp=os.path.join(root,f); print(" ",os.path.relpath(fp,td),repr(open(fp).read()[:400]))

