import re, pathlib, json
opts={}
for cmd in ["add-environment","diff","format","init","lint","pull","push","version"]:
    txt=pathlib.Path(f"/tmp/probe/help-{cmd}.txt").read_text()
    s=set()
    for line in txt.splitlines():
        # option lines start spaces then maybe -x, --name
        m=re.match(r'\s+(?:-([A-Za-z0-9?]),\s+)?--(\[skip-\])?([a-z0-9\-]+)', line)
        if m:
            s.add((m.group(3), m.group(1)))
        else:
            m=re.match(r'\s+--(\[skip-\])?([a-z0-9\-]+)', line)
            if m: s.add((m.group(2),None))
    opts[cmd]=sorted(s)
    print(cmd, [x[0] for x in sorted(s)])
print("union", sorted(set(x[0] for v in opts.values() for x in v)))
