# ----------------------------------------------------------------------------
# Logging
# ----------------------------------------------------------------------------

_debug_enabled = False

def _timestamp():
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")

def log_msg(level, message):
    # Debug messages are only emitted if debug mode is currently enabled.
    if level == "DEBUG" and not _debug_enabled:
        return
    if message is None:
        message = ""
    # Each physical line gets its own prefix, matching the original logger
    # for the multi-line messages we construct explicitly.
    lines = str(message).split("\n")
    pad = " " * max(1, 6 - len(level))
    for line in lines:
        sys.stderr.write(f"{_timestamp()} [{level}]{pad}{line}\n")
    sys.stderr.flush()

def log_info(msg): log_msg("INFO", msg)
def log_warn(msg): log_msg("WARN", msg)
def log_error(msg): log_msg("ERROR", msg)
def log_debug(msg): log_msg("DEBUG", msg)

def driver_log(message):
    # Messages emitted by the MySQL driver in the original (Go) binary use
    # the standard Go log format and go to stderr.
    ts = datetime.now(timezone.utc).strftime("%Y/%m/%d %H:%M:%S")
    sys.stderr.write(f"[mysql] {ts} {message}\n")
    sys.stderr.flush()

