def normalize_opt_name(name):
    return name.strip().lower().replace("_", "-")

def split_negation(normalized):
    for prefix in ("skip-", "disable-"):
        if normalized.startswith(prefix):
            return normalized[len(prefix):], True
    return normalized, False

def is_truthy(value):
    if value is None:
        return False
    return value.strip().lower() not in ("", "0", "false", "off")

def is_falsy_str(value):
    return not is_truthy(value)

# ----------------------------------------------------------------------------
# Option files (.skeema, ~/.skeema, ~/.my.cnf)
# ----------------------------------------------------------------------------

class FileOption:
    __slots__ = ("name", "raw", "has_value", "negated")
    def __init__(self, name, raw, has_value, negated):
        self.name = name
        self.raw = raw          # textual value after comment strip, quotes kept
        self.has_value = has_value
        self.negated = negated

class OptionFile:
    def __init__(self, path):
        self.path = path
        self.sections = []      # list of section names in order of appearance
        self.data = {}          # section -> dict name -> FileOption
    def ensure_section(self, name):
        if name not in self.data:
            self.data[name] = {}
            self.sections.append(name)
        return self.data[name]
    def section_options(self, section):
        return self.data.get(section, {})
    def set_option(self, section, fo):
        self.ensure_section(section)[fo.name] = fo
    def has_section(self, name):
        return name in self.data

def _strip_hash_comment(value):
    """Remove a # comment that is outside quotes. Returns the remainder."""
    in_s = in_d = False
    i = 0
    while i < len(value):
        c = value[i]
        if in_s:
            if c == "\\":
                i += 2; continue
            if c == "'":
                in_s = False
        elif in_d:
            if c == "\\":
                i += 2; continue
            if c == '"':
                in_d = False
        else:
            if c == "'": in_s = True
            elif c == '"': in_d = True
            elif c == "#":
                return value[:i]
        i += 1
    return value

def unquote_value(raw, path, lineno):
    """Compute the runtime value of an option-file value: strip hash
    comments, trim, remove surrounding quotes (repeatedly), expand a
    leading $ENV reference."""
    v = _strip_hash_comment(raw).strip()
    # Environment expansion happens when the (unquoted-check) value starts
    # with $, before quotes are considered.
    if v.startswith("$") and not (v.startswith("'") or v.startswith('"')):
        varname = v[1:]
        return os.environ.get(varname, "")
    # Repeatedly strip a matched pair of surrounding quotes
    while len(v) >= 2 and v[0] in ("'", '"'):
        q = v[0]
        # find closing quote
        idx = -1
        i = 1
        while i < len(v):
            if v[i] == "\\":
                i += 2; continue
            if v[i] == q:
                idx = i; break
            i += 1
        if idx == -1:
            raise ConfigError(f'Parse error in {path} line {lineno}: Quoted value has no terminating quote')
        inner = v[1:idx]
        rest = v[idx+1:].strip()
        if rest:
            # trailing junk after quoted value: keep whole thing minus quotes?
            v = (inner + rest).strip()
            break
        v = inner.strip()
        # loop again in case of nested quotes; guard
        if not (len(v) >= 2 and v[0] in ("'", '"')):
            break
    return v

def parse_option_file(path, content):
    """Parse option-file content. Raises ConfigError with the messages the
    original emits ({path} line N: ...)."""
    of = OptionFile(path)
    current = ""
    of.ensure_section("")
    for lineno, rawline in enumerate(content.split("\n"), start=1):
        line = rawline.strip().strip("\r").strip()
        if line == "" or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("["):
            close = line.find("]")
            if close == -1:
                raise ConfigError(f"Parse error in {path} line {lineno}: unterminated section name")
            name = line[1:close].strip()
            rest = line[close+1:].strip()
            if rest and not rest.startswith("#"):
                raise ConfigError(f"Parse error in {path} line {lineno}: extra characters after section name")
            current = name
            of.ensure_section(current)
            continue
        if "=" in line:
            name_part, value_part = line.split("=", 1)
            has_value = True
        else:
            name_part, value_part = line, None
            has_value = False
        normalized = normalize_opt_name(name_part)
        canonical, negated = split_negation(normalized)
        if canonical not in _ALL_DEFS:
            raise ConfigError(f'{path} line {lineno}: Unknown option "{canonical}"')
        defn = _ALL_DEFS[canonical]
        if not has_value and not negated:
            if defn.kind == STRING:
                raise ConfigError(f"{path} line {lineno}: Missing required value for option {canonical}")
            raw = ""
        else:
            raw = "" if value_part is None else value_part.strip()
            raw = _strip_hash_comment(raw).strip()
        # Validate quoted values now so parse errors surface identically
        if has_value:
            # this raises on unterminated quote
            unquote_value(raw, path, lineno)
        of.set_option(current, FileOption(canonical, raw, has_value, negated))
    return of

def option_file_to_text(of):
    out_lines = []
    first = True
    for section in of.sections:
        opts = of.data.get(section, {})
        if not first:
            out_lines.append("")
        first = False
        if section != "":
            out_lines.append(f"[{section}]")
        for name in sorted(opts.keys()):
            fo = opts[name]
            out_lines.append(_format_file_option(fo))
    return "\n".join(out_lines) + "\n"

def _format_file_option(fo):
    defn = _ALL_DEFS.get(fo.name)
    if fo.negated:
        return f"skip-{fo.name}"
    if not fo.has_value:
        return fo.name
    # runtime value for bool canonicalisation
    try:
        runtime = unquote_value(fo.raw, "", 0)
    except Exception:
        runtime = fo.raw
    if defn is not None and defn.kind == BOOL:
        if is_truthy(runtime):
            return fo.name
        return f"skip-{fo.name}"
    if fo.raw == "":
        return f"skip-{fo.name}"
    return f"{fo.name}={fo.raw}"

# ----------------------------------------------------------------------------
# Configuration (layered)
# ----------------------------------------------------------------------------

class ConfigEntry:
    __slots__ = ("value", "source", "priority", "bare")
    def __init__(self, value, source, priority, bare=False):
        self.value = value
        self.source = source    # 'default', 'command line', or a file path
        self.priority = priority
        self.bare = bare        # supplied with no value (prompt sentinel)

class Config:
    def __init__(self):
        self.entries = {}
        for name, d in _ALL_DEFS.items():
            val = d.default
            if name == "password":
                # default "$MYSQL_PWD" is resolved against the environment
                val = os.environ.get("MYSQL_PWD", "")
            self.entries[name] = ConfigEntry(val, "default", 0)
    def clone(self):
        c = Config.__new__(Config)
        c.entries = {k: ConfigEntry(v.value, v.source, v.priority, v.bare) for k, v in self.entries.items()}
        return c
    def set(self, name, value, source, priority, bare=False):
        old = self.entries.get(name)
        if old is None or priority >= old.priority:
            self.entries[name] = ConfigEntry(value, source, priority, bare)
    def get(self, name):
        e = self.entries.get(name)
        return e.value if e else ""
    def get_bool(self, name):
        return is_truthy(self.get(name))
    def source_of(self, name):
        e = self.entries.get(name)
        return e.source if e else "default"
    def changed(self, name):
        e = self.entries.get(name)
        return e is not None and e.source != "default"
    def bare(self, name):
        e = self.entries.get(name)
        return bool(e and e.bare)

def get_int_config(cfg, name):
    s = cfg.get(name).strip()
    v = _parse_go_int(s)
    return v

_INT64_MAX = 9223372036854775807
_INT64_MIN = -9223372036854775808

def _parse_go_int(s):
    s = s.strip()
    if not re.fullmatch(r"[+-]?\d+", s or ""):
        return 0
    try:
        v = int(s)
    except Exception:
        return 0
    return max(_INT64_MIN, min(_INT64_MAX, v))

def _atoi_exact(s):
    """strconv.Atoi: returns (value, error-string or None)"""
    t = s.strip()
    if not re.fullmatch(r"[+-]?\d+", t or ""):
        return None, f'strconv.Atoi: parsing "{s}": invalid syntax'
    v = int(t)
    if v > _INT64_MAX or v < _INT64_MIN:
        # Go reports range error; the binary saturates in GetInt paths, but
        # Atoi on embedded port surfaces a syntax-ish error. Approximate.
        return None, f'strconv.Atoi: parsing "{s}": value out of range'
    return v, None

def apply_option_file(cfg, of, env_name, priority, emit_deprecated=True):
    """Apply sectionless + [env] options of an option file to cfg."""
    # Determine relevant options: sectionless first, then env section
    merged = {}
    order = []
    for section in ("", env_name):
        for name, fo in of.section_options(section).items():
            if name not in merged:
                order.append(name)
            merged[name] = fo
    for name in order:
        fo = merged[name]
        if fo.negated:
            if fo.has_value:
                # skip-foo=bar sets value to the negation of bar's truthiness
                try:
                    rv = unquote_value(fo.raw, of.path, 0)
                except Exception:
                    rv = fo.raw
                value = "0" if is_truthy(rv) else "1"
            else:
                value = ""
