def _is_delimiter_directive(text, pos):
    # Only recognised at the start of a line (modulo leading spaces/tabs)
    line_start = text.rfind("\n", 0, pos) + 1
    prefix = text[line_start:pos]
    if prefix.strip(" \t") != "":
        return False
    rest = text[pos:pos+9]
    if rest.upper() != "DELIMITER":
        return False
    after = pos + 9
    if after < len(text) and (text[after].isalnum() or text[after] == "_"):
