    return True

def classify_statement(text):
    """'table', 'routine', 'ignored' (USE), or 'unsupported'"""
    # Strip leading comments/whitespace
    t = text.strip()
    while True:
        if t.startswith("--") or t.startswith("#"):
            nl = t.find("\n")
            t = "" if nl == -1 else t[nl+1:].lstrip()
            continue
        if t.startswith("/*"):
            end = t.find("*/")
