        return "unsupported"
    mm = re.match(r"([A-Za-z]+)", rest)
    if not mm:
        return "unsupported"
    kw = mm.group(1).upper()
    if kw == "TABLE":
        return _classify_create_table(rest)
    if kw in ("PROCEDURE", "FUNCTION"):
        return "routine"
    return "unsupported"

def _classify_create_table(rest):
    # rest begins at TABLE keyword
    after = rest[5:] if len(rest) > 5 else ""
    # CREATE TABLE ... AS SELECT / SELECT is unsupported (CTAS)
    if re.search(r"\bAS\s+SELECT\b", after, re.IGNORECASE) or re.search(r"\)\s*SELECT\b", after, re.IGNORECASE):
        return "unsupported"
    stripped = after.strip()
    # name then SELECT directly
    if re.match(r"^(?:IF\s+NOT\s+EXISTS\s+)?(`[^`]+`|[A-Za-z0-9_$]+)(\.[A-Za-z0-9_$`]+)?\s+SELECT\b", stripped, re.IGNORECASE):
