class Dir:
    def __init__(self, path, config, option_file, parent_display_base):
        self.path = path
        self.config = config
        self.option_file = option_file
        self.sql_files = []       # list of (filename, statements)
        self.error = None         # SkeemaError if this dir failed to load
        self.parent_display_base = parent_display_base
        self._subdirs = None
        self.password_prompted = False
    def rel_display(self):
        parent = os.path.dirname(self.parent_display_base)
        try:
            rel = os.path.relpath(self.path, parent)
        except Exception:
            rel = self.path
        return rel
    def has_schema_config(self):
        return self.config.get("schema").strip() != ""
    def has_supported(self):
        for _fn, stmts in self.sql_files:
            for st in stmts:
                if st.kind in ("table", "routine"):
                    return True
        return False
    def unsupported_notes(self):
        notes = []
        for fn, stmts in self.sql_files:
            for st in stmts:
                if st.kind == "unsupported":
                    notes.append((os.path.join(self.path, fn), st.line, st.col))
