def _read_file_bytes(path):
    with open(path, "rb") as fh:
        return fh.read()

def _go_open_error(path, e):
    if isinstance(e, IsADirectoryError):
        return f"read {path}: is a directory"
    if isinstance(e, PermissionError):
        return f"open {path}: permission denied"
    if isinstance(e, FileNotFoundError):
        return f"open {path}: no such file or directory"
    return f"open {path}: {e}"

def load_option_file_for_dir(path):
    """Returns OptionFile or None if no .skeema exists. Raises SkeemaError."""
    skeema_path = os.path.join(path, ".skeema")
    try:
        st = os.lstat(skeema_path)
    except FileNotFoundError:
        return None
    except PermissionError:
        raise SkeemaError(f"lstat {skeema_path}: permission denied", 78)
    except OSError as e:
        raise SkeemaError(f"lstat {skeema_path}: {_errno_phrase(e.errno)}", 78)
