        try:
            rst = os.stat(skeema_path)
            if not stat.S_ISREG(rst.st_mode):
                raise SkeemaError(f"{skeema_path} is not a regular file, nor a symlink to a regular file", 2)
        except SkeemaError:
            raise
        except OSError:
            raise SkeemaError(f"{skeema_path} is not a regular file, nor a symlink to a regular file", 2)
    elif not stat.S_ISREG(st.st_mode):
        raise SkeemaError(f"{skeema_path} is not a regular file, nor a symlink to a regular file", 2)
    try:
        content = _read_file_bytes(skeema_path).decode("utf-8", "surrogateescape")
    except OSError as e:
        raise SkeemaError(_go_open_error(skeema_path, e), 2)
    of = parse_option_file(skeema_path, content)
    return of

def ancestor_chain(path):
    """All ancestor directories of path, root-first, including path."""
    parts = []
    cur = path
    while True:
        parts.append(cur)
        parent = os.path.dirname(cur)
        if parent == cur:
            break
        cur = parent
    parts.reverse()
    return parts

