    """Create a Dir for path, resolving config from ancestors (above and
    including base chain) + own dir. Local option files are applied with
    priorities between global files and CLI."""
    d = Dir(path, None, None, base_path)
    # Start from global base layers (defaults, my.cnf, ~/.skeema)
    cfg = ctx.base_layers.clone()
    # Apply CLI later: we keep CLI entries in ctx.cli_layer
    chain = ancestor_chain(path)
    own_of = None
    # The nearest dir in the chain is path itself; earlier entries are ancestors
    for idx, ancestor in enumerate(chain):
        try:
            of = load_option_file_for_dir(ancestor)
        except SkeemaError as e:
            # For the base dir itself, callers treat this as fatal. For an
            # ancestor above base, also fatal at base-build time. Record
            # on the dir and let caller decide.
            d.error = e
            d.config = cfg
            return d
        if of is None:
            continue
        # Only emit deprecation warnings for files at or below the base
        # dir OR for the base chain that the original reports. The
        # original emits warnings for ancestor files of the base dir as
        # part of building it (observed), so emit for all chain files
        # except those above the base dir's ancestors? In practice the
        # whole chain is included, matching observed parent-file errors.
        emit = True
        apply_option_file_no_deprecated(cfg, of, ctx.env_name, priority=30 + idx)
