    try:
        entries = sorted(os.listdir(path))
    except OSError as e:
        if isinstance(e, PermissionError):
            d.error = SkeemaError(f"open {path}: permission denied", 2)
        else:
            d.error = SkeemaError(_go_open_error(path, e), 2)
        return d
    for name in entries:
        full = os.path.join(path, name)
        if not name.lower().endswith(".sql"):
            continue
        # only regular files (or symlinks to them)
        try:
            st = os.lstat(full)
        except OSError:
            continue
        is_reg = False
        if stat.S_ISREG(st.st_mode):
            is_reg = True
        elif stat.S_ISLNK(st.st_mode):
            try:
                is_reg = stat.S_ISREG(os.stat(full).st_mode)
            except OSError:
                is_reg = False
        if not is_reg:
            continue
        try:
            content = _read_file_bytes(full).decode("utf-8", "surrogateescape")
        except OSError as e:
            d.error = SkeemaError(_go_open_error(full, e), 2)
            return d
