    res = ctx.cli_res
    for name in res.cli_order:
        value, bare = res.cli[name]
        cfg.set(name, value.strip() if isinstance(value, str) else value, "command line", 100, bare=bare)

def subdir_names(path):
    try:
        entries = sorted(os.listdir(path))
    except OSError:
        return []
    out = []
    for name in entries:
        if name.startswith("."):
            continue
        full = os.path.join(path, name)
        try:
            st = os.lstat(full)
        except OSError:
            continue
        if stat.S_ISDIR(st.st_mode):
            out.append(name)
    return out

