    if d._subdirs is not None:
        return d._subdirs
    subs = []
    for name in subdir_names(d.path):
        full = os.path.join(d.path, name)
        sub = build_child_dir(full, d, ctx)
        subs.append(sub)
    d._subdirs = subs
    return subs

