    """Create a child Dir inheriting parent config plus its own option file."""
    d = Dir(path, None, None, parent_dir.parent_display_base)
    cfg = parent_dir.config.clone()
    # remove CLI dominance issue: parent config already has CLI at 100.
    # Child's own file must be below CLI but above parent local files.
    # Parent local priorities were assigned by chain index; re-applying
    # with a priority below 100 achieves ordering as long as parent's own
    # local value has priority < 90.
    try:
        of = load_option_file_for_dir(path)
    except SkeemaError as e:
        d.error = e
        d.config = cfg
