    if of is not None:
        # deprecation warnings for child files are emitted when the child
        # is created (observed ordering)
        apply_option_file_no_deprecated(cfg, of, ctx.env_name, priority=90)
        emit_file_deprecated(of)
        d.option_file = of
    # Re-assert CLI (already present from clone at priority 100, local at
    # 90 does not override because Config.set requires priority >= old)
    d.config = cfg
    # SQL files
    try:
        entries = sorted(os.listdir(path))
    except OSError as e:
        d.error = SkeemaError(_go_open_error(path, e) if not isinstance(e, PermissionError) else f"lstat {os.path.join(path,'.skeema')}: permission denied", 78 if isinstance(e, PermissionError) else 2)
        # The unreadable-subdir case is observed as a lstat error on the
        # .skeema path during load; approximate with the load error if set
        return d
    for name in entries:
        full = os.path.join(path, name)
        if not name.lower().endswith(".sql"):
            continue
        try:
            st = os.lstat(full)
        except OSError:
            continue
        is_reg = False
        if stat.S_ISREG(st.st_mode):
            is_reg = True
        elif stat.S_ISLNK(st.st_mode):
            try: is_reg = stat.S_ISREG(os.stat(full).st_mode)
            except OSError: is_reg = False
        if not is_reg:
            continue
        try:
            content = _read_file_bytes(full).decode("utf-8", "surrogateescape")
        except OSError as e:
            d.error = SkeemaError(_go_open_error(full, e), 2)
            return d
        try:
            stmts = split_statements(content, full)
        except SQLParseError as e:
            d.error = e
            return d
        d.sql_files.append((name, stmts))
    return d

