def _acquire_docker_workspace(cfg, fl):
    docker = shutil.which("docker")
    if docker is None:
        err = SkeemaError("unable to find `docker` command-line client among directories in PATH", 2)
        err._docker_not_found = True
        return err
    # docker info
    try:
        proc = subprocess.run([docker, "info", "--format", "{{json .}}"], capture_output=True, text=True, timeout=30)
    except OSError as e:
        return SkeemaError(f"error invoking `docker` command-line client: {e}", 2)
    if proc.returncode != 0:
        stderr = proc.stderr.strip()
        return SkeemaError(f"error invoking `docker` command-line client: exit status {proc.returncode}: {stderr}", proc.returncode if proc.returncode else 2)
    out = proc.stdout.strip()
    if out == "":
        return SkeemaError("error decoding JSON response from `docker` command-line client: unexpected end of JSON input", 2)
    try:
        info = json.loads(out)
    except Exception:
        return SkeemaError(f"error decoding JSON response from `docker` command-line client: {_go_json_error(out)}", 2)
    if not isinstance(info, dict):
