    try:
        proc = subprocess.run([docker, "start", container], capture_output=True, text=True, timeout=30)
    except OSError as e:
        return SkeemaError(str(e), 2)
    if proc.returncode != 0:
        stderr = proc.stderr.strip()
        code = proc.returncode if proc.returncode else 2
        return SkeemaError(f"exit status {code}: {stderr}", code)
    # Inspect port mapping (a few attempts)
    port = None
    for _ in range(5):
        try:
            proc = subprocess.run([docker, "inspect", "--type", "container", "--format={{json .NetworkSettings.Ports}}", container], capture_output=True, text=True, timeout=30)
        except OSError as e:
            return SkeemaError(str(e), 2)
        if proc.returncode == 0:
            try:
                data = json.loads(proc.stdout.strip())
                mappings = data.get("3306/tcp") or []
                if mappings:
                    port = int(mappings[0].get("HostPort"))
                    break
            except Exception:
                return SkeemaError(f"Unable to find port mapping for container {container}: unable to decode JSON response from `docker` command-line client: json: cannot unmarshal string into Go value of type []map[string]string", 2)
