# ----------------------------------------------------------------------------
# Shared handler helpers
# ----------------------------------------------------------------------------

def get_base_dir(ctx):
    """Build the Dir for the current working directory. Raises SkeemaError
    (fatal) if it cannot be loaded."""
    base = clean_abs_path(os.getcwd())
    ctx.prompt_dirs = ctx.cli_res.command in ("lint", "format")
    d = build_dir(base, ctx, base)
    if d.error is not None:
        raise d.error
    if ctx.prompt_dirs:
        maybe_prompt_dir_password(d)
    return d

def validate_ignore_regexes(cfg):
    for name in ("ignore-schema", "ignore-table", "ignore-func", "ignore-proc"):
        pat = cfg.get(name)
        if pat != "":
            try:
                re.compile(pat)
            except re.error:
                raise ConfigError(f"Invalid regexp for option {name}: {pat}")

def validate_concurrent(cfg):
    s = cfg.get("concurrent-servers").strip()
    if s != "":
        # matches strconv.Atoi error surface for diff/push
        if not re.fullmatch(r"[+-]?\d+", s):
            raise SkeemaError(f'strconv.Atoi: parsing "{s}": invalid syntax', 2)

def result_code_aggregation(codes):
    if not codes:
        return 0
    return max(codes)

# ----------------------------------------------------------------------------
# help / version
# ----------------------------------------------------------------------------

def print_help_for(name):
    if name is None:
        sys.stdout.write(HELP_TEXTS["main"])
    else:
        sys.stdout.write(HELP_TEXTS[name])
    sys.stdout.flush()

def handle_help_command(ctx):
    """The `help` subcommand. Returns None (success) or an exit code."""
    args = ctx.cli_res.args
    if not args:
        print_help_for(None)
        return None
    target = args[0]
    if target == "help":
        print_help_for(None)
        return None
    if target == "version":
        sys.stdout.write(VERSION_STRING + "\n")
        return None
    if target in COMMANDS:
        print_help_for(target)
        return None
    log_error(f'Unknown command "{target}"')
    return 2

def handle_version_command(ctx):
    sys.stdout.write(VERSION_STRING + "\n")
    return None

