    instances_hosts = [host]
    wrapper = cfg.get("host-wrapper").strip()
    if wrapper != "":
        hosts, err = run_host_wrapper(cfg, d)
        if err is not None:
            return [], err
        instances_hosts = hosts
        if not instances_hosts:
            return [], TargetError("emptywrapper")
    insts = []
    for h in instances_hosts:
        c2 = cfg.clone()
        c2.set("host", h, cfg.source_of("host"), 95)
        try:
            inst = Instance(c2, for_dir=d.path)
        except SkeemaError as e:
