    template = cfg.get("host-wrapper")
    variables = {
        "HOST": cfg.get("host").strip(),
        "SCHEMA": cfg.get("schema").strip(),
        "ENVIRONMENT": ctx_env_name_global[0],
    }
    # variable substitution
    out = []
    i = 0
    while i < len(template):
        if template[i] == "{":
            close = template.find("}", i)
            if close == -1:
                out.append(template[i]); i += 1; continue
            var = template[i+1:close]
            if var not in variables:
                return None, TargetError(f"Unknown variable {var}")
            out.append(variables[var])
            i = close + 1
        else:
            out.append(template[i]); i += 1
    command = "".join(out)
    proc = subprocess.run(["/bin/sh", "-c", command], capture_output=True, text=True)
