    for d in error_dirs:
        items.append((d.path, "error", d))
    items.sort(key=lambda x: x[0])
    problems = 0
    for _path, kind, d in items:
        if kind == "error":
            log_error(f"Skipping {d.path}: {d.error.message}")
            problems += 1
            continue
        cfg = d.config
