                log_warn(f"This command requires a hostname, which can be specified using the host option in a [{ctx.env_name}] section of the .skeema file in this directory, or in a parent directory.")
                continue
            log_error(f"Skipping {d.path}: {terr.message}")
            problems += 1
            continue
        for inst in insts:
            # password prompting per instance if needed
            if d.config.bare("password"):
                pw_prompt = f"Enter password for {inst.user}@{inst}: "
                pw, err = prompt_password(pw_prompt)
                if err is not None:
                    log_error(f"Skipping {d.path}: Unable to prompt password for {inst.user}@{inst}: {err}")
                    problems += 1
                    continue
                else:
