                    try:
                        inst = Instance(d.config, for_dir=d.path)
                    except SkeemaError as e:
                        log_error(f"Skipping {d.path}: {e.message}")
                        problems += 1
                        continue
            err = attempt_connection(inst)
            if err is not None:
                # password / DSN errors already have full text in err only
                # for "Unable to connect" style; attempt_connection returns
                # the dial suffix, so wrap as observed.
                if err.startswith("Unable to connect") or err.startswith("Invalid connection") or err.startswith("Invalid connection options"):
                    log_error(f"Skipping {d.path}: {err}")
                else:
                    log_error(f"Skipping {inst} for {d.path}: {err}")
                problems += 1
                continue
            # Connected to a plausible MySQL handshake: without a full
            # client we cannot diff. The original would query the server
            # here. Treat as no further output.
    if problems:
        log_error(f"Skipped {problems} operation{'s' if problems != 1 else ''} due to problem{'s' if problems != 1 else ''}")
        return 2
    return None

