def collect_targets(base, ctx):
    """Collect target dirs for diff/push. Returns a list of Dir objects in
    traversal order (dirs with their own .skeema defining/affecting schema
    handling, plus the base dir itself). Implemented as a full walk where
    a dir counts as relevant if it has a schema in merged config and
    (it is the base dir, or it has its own .skeema file, or an ancestor
    chain introduces it). In practice the observed behaviour is: walk
    everything; a dir is a target if its merged config has a schema and
    it is not strictly below another target dir unless it has its own
    .skeema file explicitly setting schema."""
    targets = []
    errors = []  # list of (dir, error)
    def own_file_sets_schema(d):
        if d.option_file is None:
            return False
        of = d.option_file
        for section in ("", ctx.env_name):
            if "schema" in of.section_options(section):
                v = of.section_options(section)["schema"]
                if not v.negated:
                    try:
                        if unquote_value(v.raw, of.path, 0).strip() != "":
                            return True
                    except Exception:
                        return True
