# ----------------------------------------------------------------------------
# pull
# ----------------------------------------------------------------------------

def handle_pull(ctx):
    base = get_base_dir(ctx)
    validate_ignore_regexes(base.config)
    if _debug_enabled and not base.config.changed("format"):
        log_debug("Upgrade notice: the --format option, which currently defaults to true in Skeema v1, will change to default to false in Skeema v2. For more information, visit https://www.skeema.io/v2-changes")
    state = {"codes": []}
    pull_walk(base, ctx, state, is_base=True)
    if state["codes"]:
        return result_code_aggregation(state["codes"])
    return 0

def pull_walk(d, ctx, state, is_base=False):
    if d.error is not None:
        if is_base:
            raise d.error
        log_warn(f"Skipping {d.path}: {d.error.message}")
        state["codes"].append(d.error.code)
        return
    cfg = d.config
    host = cfg.get("host").strip()
    if host != "":
        # host dir: a single operation
        err = pull_one_host_dir(d, ctx)
        if err is not None:
            level_msg, code = err
            # pull_one_host_dir already logged; just record code
            state["codes"].append(code)
        return
    if d.has_schema_config():
        log_error(f"Skipping {d.path}: No host defined for environment \"{ctx.env_name}\"")
        log_error(f"This command requires a hostname to pull from, which can be specified using the host option in a [{ctx.env_name}] section of the .skeema file in this directory, or in a parent directory.")
        state["codes"].append(78)
        return
    subs = build_subdirs(d, ctx)
    for sub in subs:
        pull_walk(sub, ctx, state)

def pull_one_host_dir(d, ctx):
    cfg = d.config
    # expand via host-wrapper if present
    insts, terr = expand_instances_for_target(d, ctx)
    if terr is not None:
        if terr.message == "emptywrapper":
            log_warn(f"Skipping {d.path}: directory maps to an empty list of database servers")
            log_warn("The host-wrapper option controls which hosts this directory maps to, but the executed script returned no hostnames.")
            return (None, 1)
        log_warn(f"Skipping {d.path}: {terr.message}")
        return (None, 1)
    worst = None
    for inst in insts:
        if d.config.bare("password"):
            pw, err = prompt_password(f"Enter password for {inst.user}@{inst}: ")
            if err is not None:
                log_warn(f"Skipping {d.path}: Unable to prompt password for {inst.user}@{inst}: {err}")
                worst = 1
                continue
            d.config.set("password", pw, d.config.source_of("password"), 100, bare=False)
            try:
                inst = Instance(d.config, for_dir=d.path)
            except SkeemaError as e:
                log_warn(f"Skipping {d.path}: {e.message}")
                worst = 1
                continue
        err = attempt_connection(inst)
        if err is not None:
            if err.startswith("Invalid"):
                log_warn(f"Skipping {d.path}: {err}")
            else:
                log_warn(f"Skipping {d.path}: Unable to connect to {inst} for {d.path}: {err}")
            worst = 1
            continue
    if worst is not None:
        return (None, worst)
    return None

# ----------------------------------------------------------------------------
# init
# ----------------------------------------------------------------------------

def handle_init(ctx):
    cfg = ctx.global_config
    res = ctx.cli_res
    # --host must be supplied on the command line specifically
    if "host" not in res.cli:
        raise ConfigError("Option --host must be supplied on the command-line")
    # First build instance-ish info for default dir naming
    host_cli_value = cfg.get("host")
    # Compute directory path
    dir_opt = cfg.get("dir")
    dir_changed = cfg.changed("dir")
    # Build a provisional instance for naming (may raise embedded-port errors)
    # Default dir name depends on host/port-changed as per Instance logic
    provisional = None
    naming_error = None
    try:
        provisional = _make_instance_for_init(cfg, for_dir=None, provisional=True)
    except SkeemaError as e:
        naming_error = e
    if dir_changed and res.cli.get("dir", (None, False))[0] is not None and cfg.source_of("dir") == "command line" or dir_changed:
        # dir option set somewhere (CLI or global); its value is used verbatim
        dir_name = dir_opt
    else:
        dir_name = dir_opt
    if not dir_changed:
        if provisional is not None:
            dir_name = provisional.default_dir_name()
        else:
            dir_name = host_cli_value.strip()
    target_path = clean_abs_path(dir_name) if dir_name != "" else ""
    # Create the directory (MkdirAll semantics)
    if target_path == "":
        raise SkeemaError("Cannot create dir : mkdir : no such file or directory", EX_CANTCREAT)
    try:
        os.makedirs(target_path, exist_ok=True)
    except OSError as e:
        # messages use the supplied dir argument when --dir was used
        shown = dir_name
        if isinstance(e, NotADirectoryError):
            raise SkeemaError(f"Cannot create dir {shown}: mkdir {shown}: not a directory", EX_CANTCREAT)
        if isinstance(e, FileExistsError):
            raise SkeemaError(f"Cannot create dir {shown}: mkdir {shown}: file exists", EX_CANTCREAT)
        if isinstance(e, PermissionError):
            raise SkeemaError(f"Cannot create dir {shown}: mkdir {shown}: permission denied", EX_CANTCREAT)
        raise SkeemaError(f"Cannot create dir {shown}: mkdir {shown}: {_errno_phrase(getattr(e, 'errno', None))}", EX_CANTCREAT)
    # Load the dir: parse errors in its .skeema surface directly
    # (build a dir for target path; parents are ancestors of target)
    dir_obj = build_dir(target_path, ctx, target_path)
    if dir_obj.error is not None:
        raise dir_obj.error
    if dir_obj.option_file is not None:
        raise ConfigError(f"Cannot use dir {target_path}: already has .skeema file")
    # schema defined by an ancestor/global option file (not the CLI)?
    schema_val = cfg.get("schema").strip()
    # merged dir config knows schema source
    merged_cfg = dir_obj.config
    if merged_cfg.get("schema").strip() != "" and merged_cfg.source_of("schema") != "command line":
        raise ConfigError(f"Cannot use dir {target_path}: an ancestor option file defines schema option")
    if naming_error is not None:
        raise naming_error
    # Build the real instance now (instance errors surface as-is)
    inst = _make_instance_for_init(cfg, for_dir=target_path)
    # host emptiness check as observed
    if inst.host.strip() == "":
        raise ConfigError("Command line did not specify which database server to connect to")
    err = attempt_connection(inst)
    if err is not None:
        raise SkeemaError(f"Unable to connect to {inst} for {target_path}: {err}", 2)
    # A real server answered the handshake; importing schemas requires a
    # full MySQL client session, which we cannot complete.
    return None

def _make_instance_for_init(cfg, for_dir, provisional=False):
    return Instance(cfg, for_dir=for_dir)

