        if "host" in opts:
            fo = opts["host"]
            if not fo.negated:
                try:
                    if unquote_value(fo.raw, skeema_path, 0).strip() != "":
                        has_host = True
                except Exception:
                    has_host = True
    if "host" not in res.cli:
        raise ConfigError("`skeema add-environment` requires --host to be supplied on command-line")
    if not has_host:
        raise ConfigError("This command should be run against a --dir whose .skeema file already defines a host for another environment")
    # Build instance for the new environment (validates ssl etc.)
    # Host-wrapper may transform the host
    new_cfg = cfg.clone()
    insts, terr = _instances_for_addenv(new_cfg, dir_path, ctx)
    if terr is not None:
        # host-wrapper errors: bare message, exit code from shell result
        raise SkeemaError(terr.message, 126 if "exit status 126" in terr.message else 2)
    if not insts:
        raise ConfigError("Sharding configuration for host (or host-wrapper) yielded an empty list of database servers")
    inst = insts[0]
    # Try to determine flavor by connecting (best effort; warn on failure)
    flavor = None
    conn_err = attempt_connection(inst)
    if conn_err is not None:
        log_warn(f"Unable to automatically determine database server's vendor/version. To set manually, use the \"flavor\" option in {skeema_path}")
    else:
        # cannot determine vendor without a full client; still warn as
        # we cannot read the server version
        log_warn(f"Unable to automatically determine database server's vendor/version. To set manually, use the \"flavor\" option in {skeema_path}")
    # Build the new section
    new_section_opts = {}
    # Copy CLI-changed connection-ish options
    copy_names = ["connect-options", "ignore-func", "ignore-proc", "ignore-schema", "ignore-table", "ssl-mode", "user"]
    for name in res.cli_order:
        if name in copy_names:
            value, bare = res.cli[name]
            new_section_opts[name] = FileOption(name, value.strip(), True, False) if value.strip() != "" else FileOption(name, "", True, False)
            if value.strip() == "":
                # SetOption with empty value renders as a bare name
                new_section_opts[name] = _RawBareOption(name)
    # host/port-or-socket from instance
    host_value = inst.host
    new_section_opts["host"] = FileOption("host", _display_host_for_file(inst), True, False)
    if inst.use_socket:
        new_section_opts["socket"] = FileOption("socket", inst.socket, True, False)
    else:
        new_section_opts["port"] = FileOption("port", str(inst.port), True, False)
    if flavor:
        new_section_opts["flavor"] = FileOption("flavor", flavor, True, False)
    sec = of.ensure_section(env_name)
    for name, fo in new_section_opts.items():
        sec[name] = fo
    text = option_file_to_text(of)
    # If a copied option has an empty CLI value it should render bare; our
    # FileOption with raw "" would render skip-*, so fix those lines:
    text = _fix_bare_copies(text, env_name, new_section_opts)
    with open(skeema_path, "w") as fh:
        fh.write(text)
    log_info(f"Added environment [{env_name}] to {skeema_path}")
    return None

class _RawBareOption(FileOption):
    def __init__(self, name):
        super().__init__(name, "", False, False)

def _display_host_for_file(inst):
    return inst.host

def _fix_bare_copies(text, env_name, opts):
    # _RawBareOption already formats as bare name via _format_file_option;
    # nothing further needed.
    return text

def _instances_for_addenv(cfg, dir_path, ctx):
    host = cfg.get("host").strip()
    wrapper = cfg.get("host-wrapper").strip()
    hosts = [host]
    if wrapper != "":
        # reuse host-wrapper machinery (variables from new env config)
        saved = ctx_env_name_global[0]
        ctx_env_name_global[0] = ctx.env_name
        try:
            hosts2, err = run_host_wrapper(cfg, None)
        finally:
            ctx_env_name_global[0] = saved
        if err is not None:
            return [], err
        hosts = hosts2
    insts = []
    for h in hosts:
        c2 = cfg.clone()
        c2.set("host", h, cfg.source_of("host"), 95)
        try:
            inst = Instance(c2, for_dir=dir_path)
        except SkeemaError as e:
            # Instance creation errors in add-environment are top-level
            raise e
        insts.append(inst)
    return insts, None

