    """Returns None if a workspace is available (only dial-level success
    counts here), or a SkeemaError describing the failure."""
    cfg = d.config
    ws = cfg.get("workspace").strip()
    host = cfg.get("host").strip()
    flavor_str = cfg.get("flavor").strip()
    is_docker = ws.lower() == "docker" and flavor_str != ""
    # Instance/password resolution happens before workspace selection.
    # With workspace=docker a failed prompt is not fatal; otherwise it is.
    if is_docker:
        if host != "" and cfg.bare("password"):
            pw, err = prompt_password(_instance_prompt_text(cfg, d))
            if err is None:
                cfg.set("password", pw, cfg.source_of("password"), 100, bare=False)
            else:
                cfg.set("password", "", cfg.source_of("password"), 100, bare=False)
        fl = parse_flavor(flavor_str)
        if fl is None:
            return SkeemaError("no flavor supplied", 2)
        for w in flavor_warnings(fl):
            log_warn(w)
        return _acquire_docker_workspace(cfg, fl)
    if ws.lower() == "docker" and host == "" and flavor_str == "":
        return ConfigError(f'This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment "{env_name}"')
    if ws.lower() == "docker" and flavor_str != "" and host == "":
        # handled above by is_docker; this is unreachable, kept for clarity
        pass
    # temp-schema (any other workspace value behaves as temp-schema)
    if host == "":
        return ConfigError(f'This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment "{env_name}"')
    insts, terr = instances_for_dir(cfg, d, env_name)
    if terr is not None:
        if terr == "__empty__":
            return ConfigError(f'This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment "{env_name}"')
        return SkeemaError(terr, 78)
    if not insts:
        return ConfigError(f'This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment "{env_name}"')
    # password prompt (aggregated over instances)
    if cfg.bare("password"):
        labels = " and ".join(f"{inst.user}@{inst.host}" for inst in insts)
        pw, err = prompt_password(f"Enter password for {labels}: ")
        if err is not None:
            return SkeemaError(f"Unable to prompt password for {labels}: {err}", 78)
        cfg.set("password", pw, cfg.source_of("password"), 100, bare=False)
        # rebuild instances with the entered password
        insts2, terr2 = instances_for_dir(cfg, d, env_name)
        if terr2 is None and insts2:
            insts = insts2
    last_err = None
    for inst in insts:
        err = attempt_connection(inst)
        if err is None:
            return None
        last_err = err
    if len(insts) > 1:
        return SkeemaError(f"Unable to connect to any of {len(insts)} database servers for {d.path}; last error {last_err}", 78)
    return SkeemaError(f"Unable to connect to {insts[0]} for {d.path}: {last_err}", 78)

def _instance_prompt_text(cfg, d):
    # Used for the docker path, where only a best-effort prompt occurs.
    try:
        insts, terr = instances_for_dir(cfg, d, "production")
        if insts:
            labels = " and ".join(f"{i.user}@{i.host}" for i in insts)
            return f"Enter password for {labels}: "
    except Exception:
        pass
    return f"Enter password for {cfg.get('user')}@{cfg.get('host').strip()}: "

def instances_for_dir(cfg, d, env_name):
    """Expand host/host-wrapper into Instance objects. Returns
    (instances, error_message_or_None). '__empty__' signals an empty
    host-wrapper result."""
    host = cfg.get("host").strip()
    wrapper = cfg.get("host-wrapper").strip()
    hosts = [host]
    if wrapper != "":
        hosts2, err = run_host_wrapper_for(cfg, env_name)
        if err is not None:
            return [], err
        if not hosts2:
            return [], "__empty__"
        hosts = hosts2
    insts = []
    for h in hosts:
        c2 = cfg.clone()
        c2.set("host", h, cfg.source_of("host"), 95)
        try:
            inst = Instance(c2, for_dir=(d.path if d else None))
        except SkeemaError as e:
            return [], e.message
        insts.append(inst)
    return insts, None

def run_host_wrapper_for(cfg, env_name):
    template = cfg.get("host-wrapper")
    variables = {
        "HOST": cfg.get("host").strip(),
        "SCHEMA": cfg.get("schema").strip(),
        "ENVIRONMENT": env_name,
    }
    out = []
    i = 0
    while i < len(template):
        if template[i] == "{":
            close = template.find("}", i)
            if close == -1:
                out.append(template[i]); i += 1; continue
            var = template[i+1:close]
            if var not in variables:
                return None, f"Unknown variable {var}"
            out.append(variables[var])
            i = close + 1
        else:
            out.append(template[i]); i += 1
    command = "".join(out)
    proc = subprocess.run(["/bin/sh", "-c", command], capture_output=True, text=True)
    if proc.stderr:
        sys.stderr.write(proc.stderr)
        sys.stderr.flush()
    if proc.returncode != 0:
        return None, f"exit status {proc.returncode}"
    hosts = []
    for line in proc.stdout.splitlines():
        line = line.strip()
        if line:
            hosts.append(line)
    return hosts, None

'''
