def _flavor_from_server(comment, version):
    c = (comment or "").lower()
    if "mariadb" in c:
        vendor = "mariadb"
    elif "percona" in c:
        vendor = "percona"
    else:
        vendor = "mysql"
    # version may contain suffixes
    core = re.split(r"[-+]", (version or "").strip())[0]
    parts = core.split(".")
    nums = []
    for part in parts[:3]:
        nums.append(int(part) if part.isdigit() else 0)
    while len(nums) < 3:
        nums.append(0)
    return (vendor, nums[0], nums[1], nums[2])

