    except OSError as e:
        return SkeemaError(str(e), 2)
    if proc.returncode != 0:
        stderr = proc.stderr.strip()
        code = proc.returncode if proc.returncode else 2
        return SkeemaError(f"exit status {code}: {stderr}", code)
    port = None
    for _ in range(5):
