                data = json.loads(proc.stdout.strip())
                mappings = data.get("3306/tcp") or []
                if mappings:
                    port = int(mappings[0].get("HostPort"))
                    break
            except Exception:
                return SkeemaError(f"Unable to find port mapping for container {container}: unable to decode JSON response from `docker` command-line client: json: cannot unmarshal string into Go value of type []map[string]string", 2)
    if port is None:
        return SkeemaError(f"Unable to find port mapping for container {container}", 2)
    inst_cfg = cfg.clone()
    inst_cfg.set("host", "127.0.0.1", "command line", 100)
    inst_cfg.set("port", str(port), "command line", 100)
    inst_cfg.set("socket", "/tmp/mysql.sock", "default", 0)
    try:
        inst = Instance(inst_cfg, for_dir=None)
    except SkeemaError as e:
        return e
    err = attempt_connection(inst)
    if err is not None:
        return SkeemaError(err, 2)
    return None

def _flavor_image(fl):
    vendor = fl.vendor if fl.vendor != "unknown" else "mysql"
    if fl.major == 0 and fl.minor == 0:
