    vendor = fl.vendor if fl.vendor != "unknown" else "mysql"
    if fl.major == 0 and fl.minor == 0:
        return vendor
    if fl.patch:
        return f"{vendor}:{fl.major}.{fl.minor}.{fl.patch}"
    return f"{vendor}:{fl.major}.{fl.minor}"

def _go_json_error(out):
    s = out.strip()
    if s == "":
        return "unexpected end of JSON input"
    first = s[0]
    if first == "n" and len(s) > 1:
        return f"invalid character '{s[1]}' in literal null (expecting 'u')"
    if first == "t" and len(s) > 1:
        return f"invalid character '{s[1]}' in literal true (expecting 'r')"
    if first == "f" and len(s) > 1:
        return f"invalid character '{s[1]}' in literal false (expecting 'a')"
    if first not in "{[\\"0123456789-tfn":
        return f"invalid character '{first}' looking for beginning of value"
    return "invalid character '\\\\n' in string literal" if "\\n" in s else "unexpected end of JSON input"

