        raise SkeemaError(f"Cannot examine schemas on {inst}: {qerr}", 2)
    schema_opt = cfg.get("schema").strip()
    ignore_pat = cfg.get("ignore-schema")
    schemas = []
    if schema_opt:
        charset = collation = None
        for r in rows or []:
            if r and r[0] == schema_opt:
                charset = r[1] if len(r) > 1 else None
                collation = r[2] if len(r) > 2 else None
