            raise SkeemaError(f"Cannot examine schemas on {inst}: {terr}", 2)
        for trow in trows or []:
            if not trow or len(trow) < 2:
                continue
            tname, ttype = trow[0], (trow[1] or "")
            if ttype != "BASE TABLE":
                continue
            crows, cerr = session.query(f"SHOW CREATE TABLE {_escape_ident(schema_name)}.{_escape_ident(tname)}")
            if cerr is not None or not crows or len(crows[0]) < 2:
                raise SkeemaError(f"Cannot examine schemas on {inst}: {cerr or 'no create statement returned'}", 2)
            create_sql = crows[0][1] or ""
            if not cfg.get_bool("include-auto-inc"):
                create_sql = re.sub(r"\\s+AUTO_INCREMENT=\\d+", "", create_sql)
            if cfg.get_bool("strip-partitioning"):
                create_sql = re.split(r"\\n/\\*!\\d+ PARTITION BY |\\s+PARTITION BY ", create_sql)[0]
            objects.append((f"{tname}.sql", create_sql.rstrip() + ";\\n"))
        rrows, rerr = session.query(f"SELECT routine_name, routine_type FROM information_schema.routines WHERE routine_schema = '{schema_name.replace(chr(39), chr(39)*2)}' AND routine_definition IS NOT NULL")
        if rerr is None:
            for rrow in rrows or []:
                if not rrow or len(rrow) < 2:
                    continue
                rname, rtype = rrow[0], (rrow[1] or "").upper()
                if rtype not in ("PROCEDURE", "FUNCTION"):
                    continue
                crows, cerr = session.query(f"SHOW CREATE {rtype} {_escape_ident(schema_name)}.{_escape_ident(rname)}")
                if cerr is not None or not crows or len(crows[0]) < 3:
                    continue
                create_sql = crows[0][2] or ""
                content = f"DELIMITER //\\n{create_sql.rstrip()}//\\nDELIMITER ;\\n"
                objects.append((f"{rname}.sql", content))
        result.append((schema_name, charset, collation, objects))
    return result

def _init_write_host_dir(schemas_data, inst, cfg, ctx, target_path):
    res = ctx.cli_res
