            sec["default-collation"] = FileOption("default-collation", collation, True, False)
    sec["generator"] = FileOption("generator", "skeema:1.13.2-community", True, False)
    if single:
        sec["schema"] = FileOption("schema", schema_opt, True, False)
    env_sec = host_of.ensure_section(ctx.env_name)
    copy_names = ["connect-options", "ignore-func", "ignore-proc", "ignore-schema", "ignore-table", "ssl-mode", "user"]
    for name in res.cli_order:
        if name in copy_names:
            value, bare = res.cli[name]
            if value.strip() == "":
                env_sec[name] = _RawBareOption(name)
            else:
                env_sec[name] = FileOption(name, value.strip(), True, False)
