        env_sec["flavor"] = FileOption("flavor", f"{vendor}:{major}.{minor}", True, False)
    env_sec["host"] = FileOption("host", inst.host, True, False)
    if inst.use_socket:
        env_sec["socket"] = FileOption("socket", inst.socket, True, False)
    else:
        env_sec["port"] = FileOption("port", str(inst.port), True, False)
    _write_text_file(os.path.join(target_path, ".skeema"), option_file_to_text(host_of))
    for (schema_name, charset, collation, objects) in schemas_data:
