            ssec["schema"] = FileOption("schema", schema_name, True, False)
            _write_text_file(os.path.join(schema_dir, ".skeema"), option_file_to_text(schema_of))
        for filename, content in objects:
            _write_text_file(os.path.join(schema_dir, filename), content)

def _write_text_file(path, content):
